{"thought":"I need to count bonds for iodine atoms from connected.csv and calculate the average.","action":"execute_python","action_input":"import csv

bond_counts = {}
with open('csv/connected.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        atom1 = row['atom_id']
        atom2 = row['atom_id2']
        bond_id = row['bond_id']
        if atom1 not in bond_counts:
            bond_counts[atom1] = set()
        bond_counts[atom1].add(bond_id)
        if atom2 not in bond_counts:
            bond_counts[atom2] = set()
        bond_counts[atom2].add(bond_id)

iodine_atoms = ['TR110_2', 'TR110_3', 'TR110_4', 'TR340_26', 'TR340_44', 'TR340_8']
bond_counts_per_atom = {}
for atom in iodine_atoms:
    if atom in bond_counts:
        bond_counts_per_atom[atom] = len(bond_counts[atom])
    else:
        bond_counts_per_atom[atom] = 0

total_bonds = sum(bond_counts_per_atom.values())
avg = total_bonds / len(bond_counts_per_atom) if len(bond_counts_per_atom) > 0 else 0
print(f'Average bonds per iodine atom: {avg}')
print(f'Bond counts per iodine atom: {bond_counts_per_atom}')"}
